public static boolean isAllowedToWriteTo(String gpsLoggerFolder) {

    if(Strings.isNullOrEmpty(gpsLoggerFolder)){
        return false;
    }

    File folder = new File(gpsLoggerFolder);

    if(!folder.exists()){
        folder.mkdirs();
    }

    if(!folder.exists() || !folder.isDirectory() || !folder.canWrite()){
        LOG.warn("Folder does not exist or is not writable - " + gpsLoggerFolder);
        return false;
    }

    // canWrite() can't always be trusted (permissions may have been revoked, or the
    // folder may be inaccessible due to scoped storage), so actually attempt a write.
    File testFile = new File(folder, ".gpslogger_write_test");
    OutputStream testStream = null;
    try {
        testStream = new FileOutputStream(testFile);
        testStream.write("gpslogger".getBytes());
        testStream.flush();
        return true;
    }
    catch (Exception e) {
        LOG.warn("Could not write a test file to " + gpsLoggerFolder, e);
        return false;
    }
    finally {
        Streams.closeQuietly(testStream);
        try {
            if(testFile.exists()){
                testFile.delete();
            }
        }
        catch (Exception ignored) { }
    }
}

/**
 * Lets the rest of the app (and therefore the user) know that GPSLogger could not write
 * to one of its log files.  Without this, log data is silently lost.
 */
public static void notifyWriteFailure(String loggerName, File file, Throwable throwable) {
    notifyWriteFailure(loggerName, file == null ? "" : file.getName(), throwable);
}

public static void notifyWriteFailure(String loggerName, String fileName, Throwable throwable) {
    String message = (throwable == null || Strings.isNullOrEmpty(throwable.getMessage()))
            ? fileName
            : throwable.getMessage();

    LOG.error("Could not write to file " + fileName + " (" + loggerName + ")", throwable);

    try {
        EventBus.getDefault().post(new ServiceEvents.FileWriteFailure(loggerName, fileName, message, throwable));
    }
    catch (Throwable t) {
        LOG.error("Could not inform the user of the file writing failure", t);
    }
}

