@EventBusHook
public void onEventMainThread(ServiceEvents.FileWriteFailure fileWriteFailure){

    //Don't nag the user repeatedly, one message a minute is plenty.
    if(System.currentTimeMillis() - lastWriteFailureMessageTime < 60000){
        return;
    }

    lastWriteFailureMessageTime = System.currentTimeMillis();

    Toast.makeText(getApplicationContext(), getString(R.string.could_not_write_to_file), Toast.LENGTH_LONG).show();

    try {
        String errorMessage = getString(R.string.pref_logging_file_no_permissions)
                + "<br /><br />" + preferenceHelper.getGpsLoggerFolder()
                + (Strings.isNullOrEmpty(fileWriteFailure.message) ? "" : "<br /><br />" + fileWriteFailure.message);

        Dialogs.showError(getString(R.string.error), getString(R.string.could_not_write_to_file),
                errorMessage, fileWriteFailure.throwable, this);
    }
    catch (Throwable t){
        LOG.error("Could not display the file write failure message", t);
    }
}

