/**
 * Verifies that GPSLogger can actually write to the folder it has been asked to log to.
 * If it can't, the user is told about it, rather than silently losing all their data.
 */
private void checkFileWritePermissions() {

    if(!isLoggingToFiles()){
        return;
    }

    String gpsLoggerFolder = preferenceHelper.getGpsLoggerFolder();

    if (!Files.isAllowedToWriteTo(gpsLoggerFolder)) {
        Files.notifyWriteFailure("File", gpsLoggerFolder,
                new IOException(getString(R.string.pref_logging_file_no_permissions)));
    }
}

