private boolean isLoggingToFiles() {
    return preferenceHelper.shouldLogToGpx()
            || preferenceHelper.shouldLogToKml()
            || preferenceHelper.shouldLogToCSV()
            || preferenceHelper.shouldLogToNmea()
            || preferenceHelper.shouldLogToGeoJSON();
}

/**
 * When a log file couldn't be written to, tell the user about it with a notification.
 * Data loss is silent otherwise, and the user may not notice for a long time.
 */
@EventBusHook
public void onEventMainThread(ServiceEvents.FileWriteFailure fileWriteFailure) {
    showWriteFailureNotification(fileWriteFailure);
}

private void showWriteFailureNotification(ServiceEvents.FileWriteFailure fileWriteFailure) {

    //Don't spam the user, one notification a minute is plenty.
    if (System.currentTimeMillis() - lastWriteFailureNotificationTime < 60000) {
        return;
    }

    lastWriteFailureNotificationTime = System.currentTimeMillis();

    try {
        Intent contentIntent = new Intent(this, GpsMainActivity.class);
        TaskStackBuilder stackBuilder = TaskStackBuilder.create(this);
        stackBuilder.addNextIntent(contentIntent);
        PendingIntent pending = stackBuilder.getPendingIntent(1, PendingIntent.FLAG_UPDATE_CURRENT);

        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
            NotificationManager manager = (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
            NotificationChannel channel = new NotificationChannel(WRITE_FAILURE_CHANNEL,
                    getString(R.string.could_not_write_to_file), NotificationManager.IMPORTANCE_HIGH);
            channel.setShowBadge(true);
            manager.createNotificationChannel(channel);
        }

        String contentTitle = getString(R.string.could_not_write_to_file);
        StringBuilder contentText = new StringBuilder();
        contentText.append(getString(R.string.could_not_write_to_file_detail));
        if(!Strings.isNullOrEmpty(fileWriteFailure.fileName)){
            contentText.append("\n").append(fileWriteFailure.fileName);
        }
        if(!Strings.isNullOrEmpty(fileWriteFailure.message)){
            contentText.append("\n").append(fileWriteFailure.message);
        }

        NotificationCompat.Builder builder = new NotificationCompat.Builder(getApplicationContext(), WRITE_FAILURE_CHANNEL)
                .setSmallIcon(android.R.drawable.stat_notify_error)
                .setPriority(NotificationCompat.PRIORITY_HIGH)
                .setCategory(NotificationCompat.CATEGORY_ERROR)
                .setContentTitle(contentTitle)
                .setContentText(contentText.toString())
                .setStyle(new NotificationCompat.BigTextStyle().bigText(contentText.toString()).setBigContentTitle(contentTitle))
                .setAutoCancel(true)
                .setOngoing(false)
                .setContentIntent(pending);

        notificationManager = (NotificationManager) getSystemService(NOTIFICATION_SERVICE);
        notificationManager.notify(WRITE_FAILURE_NOTIFICATION_ID, builder.build());
    }

